// Types for the wasm-bindgen output in src/engine/ (generated by `npm run wasm`).
declare module "*/engine/frameling.js" {
  export default function init(input?: unknown): Promise<unknown>;
  export class Engine {
    constructor();
    load_demo(): void;
    load_blank(): void;
    load(json: string): void;
    project_json(): string;
    project_view_json(): string;
    media_data(id: string): string | undefined;
    apply(cmd: string, merge?: string): void;
    undo(): boolean;
    redo(): boolean;
    seal(): void;
    can_undo(): boolean;
    can_redo(): boolean;
    is_dirty(): boolean;
    mark_saved(): void;
    catalog(): string;
    add_pack(json: string): string;
    total_frames(): number;
    locate(frame: number): Uint32Array;
    render_scene(scene: number, local: number, width: number, height: number): Uint8Array;
    last_hits(): string;
    render_frame(frame: number, width: number, height: number): Uint8Array;
    audio_events(): string;
    render_item_preview(itemJson: string, width: number, height: number, frame: number): Uint8Array;
    render_background_preview(id: string, width: number, height: number): Uint8Array;
    item_kind(scene: number, id: string): string | undefined;
  }
}
